CREATE VIEW std_game_theme AS WITH theme_source AS (SELECT game_title, platform_name, "replace"(theme_raw, '4X (explore, expand, exploit, and exterminate)', '4X') AS theme_cleaned FROM std_inventory_game_ready WHERE (theme_raw IS NOT NULL)), theme_split AS (SELECT game_title, platform_name, main."trim"(theme_value) AS theme_value FROM theme_source , unnest(string_split(theme_cleaned, ',')) AS t(theme_value)), theme_canonical AS (SELECT game_title, platform_name, CASE  WHEN ((theme_value ~~* 'Open world')) THEN ('Open World') WHEN ((theme_value ~~* 'Science fiction')) THEN ('Science Fiction') ELSE theme_value END AS theme_name FROM theme_split)SELECT DISTINCT game_title, platform_name, theme_name FROM theme_canonical WHERE ((theme_name IS NOT NULL) AND (theme_name != ''));
